// Sanitização estrita de dados sensíveis antes de registrar o incidente
const errorData = $input.first().json;

const rawMessage = errorData.execution?.error?.message || 'Erro de execução desconhecido no workflow';
// Mascarar tokens, credenciais e chaves caso presentes no texto do erro
const sanitizedMessage = rawMessage
  .replace(/(bearer\s+)[a-zA-Z0-9_.-]+/gi, '$1[REDACTED]')
  .replace(/(key=|secret=)[a-zA-Z0-9_.-]+/gi, '$1[REDACTED]');

return [{
  json: {
    incident_id: 'inc_' + Date.now(),
    workflow_name: errorData.workflow?.name || 'Unknown',
    failed_node: errorData.execution?.lastNodeExecuted || 'Unknown',
    error_message: sanitizedMessage,
    severity: 'high',
    timestamp: new Date().toISOString()
  }
}];
